insert into public.medical_knowledge(id,topic,source_title,source_organization,source_url,source_date,verified_at,license_status,review_status,summary,warning_signs_json) values
('dehydration','Dehydration warning signs','Dehydration','NHS','https://www.nhs.uk/conditions/dehydration/','2026-05-01','2026-10-10','Original linked summary; no images or treatment regimens','source_verified','Dark urine, urinating less, thirst and dizziness can accompany dehydration. Confusion, unusual drowsiness or breathing difficulty need urgent professional attention. These signs do not establish a diagnosis.','["confusion","breathing difficulty"]'),
('allergy','Food allergies','Food allergy','NHS','https://www.nhs.uk/conditions/food-allergy/','2026-08-20','2026-10-10','Original linked summary; no images or branding','source_verified','Food allergies can cause a range of reactions. Swelling affecting the mouth or throat, breathing difficulty or faintness may be an emergency. Ask food providers about actual ingredients; a regional dish description cannot guarantee allergy safety.','["throat swelling","breathing difficulty","faintness"]'),
('anaphylaxis','Serious allergic reactions','Anaphylaxis','NHS','https://www.nhs.uk/conditions/anaphylaxis/',null,'2026-10-10','Original linked summary; UK emergency numbers and medication instructions excluded','source_verified','A serious allergic reaction can develop quickly and affect breathing or consciousness. Contact local emergency services for these warning signs. This app cannot confirm the cause or replace emergency care.','["throat swelling","breathing difficulty","loss of consciousness"]'),
('food-safety','Food safety','Safer Food Choices','CDC','https://www.cdc.gov/food-safety/foods/safer-food-choices.html','2025-01-31','2026-10-10','Original linked summary; third-party material excluded','source_verified','Safe food handling includes cleaning, separating raw foods, cooking thoroughly and chilling appropriately. Food choices and handling can reduce risk but do not guarantee that a meal or restaurant is safe.','[]')
